"""Dataset generation.

Two layers, produced independently on purpose.

**Transfer features** (amounts, payees, timing, velocity) are drawn from seeded
distributions defined below. They are synthetic and their parameters are the assumption
this whole evaluation rests on — so they are written out in full, in one place, where a
reader can disagree with them. Deterministic given `--seed`.

**Utterances** (what the customer says on the call) are generated by an LLM that is given a
plain-language description of the scam **and is never shown `scam_taxonomy.py`**. This is
the point of the exercise: the existing `victim_script` fixtures are written in the same
file as the indicator list the classifier matches against, so testing on them measures
nothing. `contamination.py` then reports how much verbatim overlap survived anyway, so the
circularity is quantified rather than assumed.

    python -m eval.generate --n 320 --seed 7
    python -m eval.generate --n 320 --no-llm     # template utterances, offline, weaker

Honest limit: synthetic data tests *internal consistency*, not real-world validity. If the
distributions below are wrong about how scams differ from legitimate transfers, every
number downstream is wrong in the same direction. Replacing this with sourced SPF /
ScamShield cases is the upgrade that makes the results externally meaningful.
"""

from __future__ import annotations

import argparse
import asyncio
import json
import random
from pathlib import Path

from app.config import get_settings
from app.schemas import CustomerProfile, ScamArchetype, TransactionRequest
from app.services.llm import LLMClient
from eval.schema import Dataset, EvalCase, Slice, utc

DATA_PATH = Path(__file__).parent / "dataset.json"

# ── Generative assumptions ─────────────────────────────────────────────────────────
# This block IS the evaluation's bias. Everything downstream inherits it.
#
# The design intent: scams and legit-suspicious transfers **share** their loud surface
# features (large amount, first-time payee), so a model cannot win on those alone. They
# differ on the quieter contextual ones (destination country, hour, velocity, memo
# pressure), which is what the risk engine claims to exploit. If we made the two slices
# identical, no feature model could ever beat chance; if we made them cleanly separable,
# every model would look excellent. Neither would tell you anything.

SCAM_PROFILE = {
    "amount_multiple": (3.0, 12.0),   # × the customer's own baseline mean
    "new_payee_p": 0.95,
    "overseas_p": 0.55,
    "off_hours_p": 0.45,
    "velocity_spike_p": 0.35,
    "pressure_memo_p": 0.50,
}
LEGIT_SUSPICIOUS_PROFILE = {
    "amount_multiple": (2.5, 10.0),   # deliberately overlapping with scams
    "new_payee_p": 0.85,              # contractors, clinics, schools are new payees too
    "overseas_p": 0.12,
    "off_hours_p": 0.10,
    "velocity_spike_p": 0.05,
    "pressure_memo_p": 0.0,
}
LEGIT_OBVIOUS_PROFILE = {
    "amount_multiple": (0.2, 1.4),
    "new_payee_p": 0.15,
    "overseas_p": 0.02,
    "off_hours_p": 0.05,
    "velocity_spike_p": 0.02,
    "pressure_memo_p": 0.0,
}

# Plain-language scam briefs. Written from how these scams are publicly known to work —
# deliberately NOT copied from the indicator lists the classifier matches on.
SCAM_BRIEFS: dict[ScamArchetype, str] = {
    ScamArchetype.government_impersonation: (
        "Someone phoned claiming to be from the police or a government agency. They told the "
        "customer their identity or bank account has been used in a crime, that they are under "
        "investigation, and that they must move their money somewhere the authorities can "
        "protect it while it is checked. They warned the customer not to discuss it with anyone."
    ),
    ScamArchetype.bank_impersonation: (
        "Someone phoned or messaged claiming to be from the customer's own bank's fraud team. "
        "They said the account has been compromised and the customer must move the balance to a "
        "new account they will provide, or confirm a code that was sent to them."
    ),
    ScamArchetype.investment: (
        "The customer was introduced, often through social media or a messaging group, to an "
        "investment opportunity promising unusually high or guaranteed returns. They have "
        "already put in a smaller amount and seen it apparently grow on a website or app, and "
        "are now sending more. They may have been told they must pay a fee to withdraw."
    ),
    ScamArchetype.romance: (
        "The customer has an online partner they have never met in person. The partner has an "
        "emergency — a medical bill, a customs charge, a stuck shipment, a business problem — "
        "and needs money urgently. Meetings have repeatedly fallen through."
    ),
    ScamArchetype.job: (
        "The customer was recruited into easy remote work, often through a messaging app: "
        "completing simple tasks, boosting orders, or writing reviews for commission. They must "
        "pay in their own funds first to unlock tasks or withdraw accumulated earnings."
    ),
    ScamArchetype.tech_support: (
        "Someone contacted the customer saying their computer or account is infected or "
        "compromised. They had the customer install software so they could connect to the "
        "machine, and now say a refund was overpaid in error and the difference must be sent back."
    ),
}

LEGIT_BRIEFS = [
    "paying a renovation contractor a staged deposit for work on their flat",
    "settling a private hospital or specialist clinic bill for a procedure",
    "sending a grandchild money towards a wedding",
    "paying a booking deposit on a property rental",
    "paying a lawyer's fee for conveyancing on a flat sale",
    "sending a sibling money to help with a family funeral",
    "paying a car dealer the balance on a second-hand vehicle",
    "paying school or university fees for a child",
    "buying furniture from a small retailer that only takes bank transfer",
    "paying a tour operator for a family holiday booked months ago",
]

_UTTERANCE_SYSTEM = (
    "You are writing realistic dialogue for a fraud-prevention research dataset. You will be "
    "given a situation describing a bank customer who is making a transfer, and you must write "
    "what THAT CUSTOMER says when their bank calls to ask about it.\n\n"
    "Write 3 short spoken replies, in the customer's own voice. They are an ordinary person in "
    "Singapore, not a fraud expert. If they are being scammed they do NOT know it — they will "
    "explain the situation sincerely, sometimes defensively, using the words the scammer gave "
    "them. Vary the vocabulary naturally between people; do not use a fixed set of stock "
    "phrases. Speech should sound spoken, not written.\n\n"
    'Return JSON: {"lines": ["...", "...", "..."]}'
)

_ADVERSARIAL_NOTE = (
    "\n\nIMPORTANT for this one: this customer is well-spoken and describes the situation in "
    "their own paraphrased words. Avoid the most obvious stock phrasings a fraud filter would "
    "look for — describe the same facts using different, less clichéd wording. The situation "
    "must remain unmistakable to a careful human reader."
)

_TEMPLATE_FALLBACK: dict[ScamArchetype, list[str]] = {
    ScamArchetype.government_impersonation: [
        "An officer rang me — he said my identity was used in a money laundering case.",
        "He told me to move my savings somewhere it can be checked and kept protected.",
        "He was very insistent I shouldn't discuss this with my family while it's ongoing.",
    ],
    ScamArchetype.bank_impersonation: [
        "Someone from the fraud department called about my account being compromised.",
        "They're moving me to a new account number they gave me over the phone.",
        "They asked me to read back the code that came through on my phone.",
    ],
    ScamArchetype.investment: [
        "It's a trading platform a friend in a chat group introduced me to.",
        "My first deposit is already showing a good return on their app.",
        "They said I need to clear a processing charge before I can take the profit out.",
    ],
    ScamArchetype.romance: [
        "He's my partner — we've been talking every day for nearly a year.",
        "He's stuck overseas and there's a charge he has to clear to get home.",
        "We were supposed to meet twice but something came up both times.",
    ],
    ScamArchetype.job: [
        "It's an online job — I complete tasks and earn commission on each one.",
        "I have to top up my own money first before the next batch unlocks.",
        "My earnings are showing in the account, I just can't withdraw them yet.",
    ],
    ScamArchetype.tech_support: [
        "A technician called about a virus on my laptop and helped me fix it.",
        "He had me install something so he could take a look remotely.",
        "He says he refunded me too much by accident and I have to send the difference back.",
    ],
}

_LEGIT_TEMPLATES = [
    "It's the deposit for the renovation work — I met the contractor at the flat.",
    "This is for my mother's operation at the clinic; I've got the invoice here.",
    "It's my grandson's wedding, we agreed I'd help with the banquet.",
    "It's the holding deposit on a rental unit, through the agent I've been dealing with.",
    "My lawyer's fee for the flat sale — nobody rang me, I arranged it myself.",
]


def _pressure_memo(rng: random.Random) -> str:
    return rng.choice([
        "urgent transfer as instructed",
        "safe account verification",
        "release fee",
        "do not tell anyone",
        "processing fee to withdraw",
    ])


def _profile(rng: random.Random, idx: int, elderly: bool) -> CustomerProfile:
    base = rng.choice([280.0, 420.0, 650.0, 1_100.0, 1_800.0, 3_200.0])
    return CustomerProfile(
        id=f"eval_cust_{idx:04d}",
        name=f"Eval Customer {idx:04d}",
        phone=f"+658{idx:07d}",
        age=rng.randint(62, 84) if elderly else rng.randint(24, 58),
        vulnerability_flags=["elderly"] if elderly else [],
        baseline_avg_amount=base,
        baseline_std_amount=base * rng.uniform(0.35, 0.7),
        typical_hour_start=rng.choice([7, 8, 9]),
        typical_hour_end=rng.choice([20, 21, 22]),
        typical_velocity_per_day=rng.uniform(0.6, 2.4),
        known_payees=[f"Known Payee {i}" for i in range(rng.randint(3, 9))],
        known_payee_phones=[f"+659{rng.randrange(10**7):07d}" for _ in range(rng.randint(2, 6))],
        home_country="SG",
    )


def _transaction(
    rng: random.Random, idx: int, cust: CustomerProfile, prof: dict
) -> tuple[TransactionRequest, list[str]]:
    """Build the transfer and record which signals a correct model ought to fire.

    Mirrors the engine's two channels exactly, because they trip different signals: a bank
    transfer (account, no phone) can fire `new_payee`; a PayNow transfer (phone) fires
    `unknown_number` instead and is the only channel where `overseas_number` is reachable.
    Getting this wrong would make Option D score the engine against an impossible target.
    """
    expected: list[str] = []
    paynow = rng.random() < 0.5

    lo, hi = prof["amount_multiple"]
    amount = round(cust.baseline_avg_amount * rng.uniform(lo, hi), -1)
    z = (amount - cust.baseline_avg_amount) / max(cust.baseline_std_amount, 1.0)
    if z > 1.0:
        expected.append("amount_anomaly")

    first_time = rng.random() < prof["new_payee_p"]
    payee_name = f"New Payee {idx}" if first_time else rng.choice(cust.known_payees)

    payee_phone: str | None = None
    country = "SG"
    if paynow:
        payee_phone = (
            f"+65{rng.randrange(10**8):08d}" if first_time else rng.choice(cust.known_payee_phones)
        )
        if first_time:
            expected.append("unknown_number")
        # Overseas is only reachable on the phone channel, and only for a new number.
        if first_time and rng.random() < prof["overseas_p"]:
            country = rng.choice(["MY", "KH", "PH", "VN"])
            payee_phone = f"+{rng.choice([60, 855, 63, 84])}{rng.randrange(10**8):08d}"
            expected.append("overseas_number")
    elif first_time:
        expected.append("new_payee")

    off_hours = rng.random() < prof["off_hours_p"]
    hour = rng.choice([1, 2, 3, 4, 23]) if off_hours else rng.randint(
        cust.typical_hour_start, cust.typical_hour_end - 1
    )
    if off_hours:
        expected.append("off_hours")

    spike = rng.random() < prof["velocity_spike_p"]
    velocity = (
        int(max(cust.typical_velocity_per_day * 2, 2) + rng.randint(1, 6))
        if spike
        else rng.randint(0, 2)
    )
    if spike:
        expected.append("velocity_spike")

    pressure = rng.random() < prof["pressure_memo_p"]
    memo = _pressure_memo(rng) if pressure else rng.choice(["", "transfer", "payment", "deposit"])
    if pressure:
        expected.append("pressure_language")

    # The engine only adds the amplifier when at least one other signal fired.
    if cust.vulnerability_flags and expected:
        expected.append("elevated_vulnerability")

    txn = TransactionRequest(
        id=f"eval_txn_{idx:04d}",
        customer_id=cust.id,
        amount=float(amount),
        payee_name=payee_name,
        payee_account=f"{rng.randrange(10**8):08d}",
        payee_phone=payee_phone,
        payee_country=country,
        channel="paynow" if paynow else "bank_transfer",
        memo=memo or None,
        requested_at=utc(days_ago=rng.uniform(0, 30), hour=hour),
        recent_transfer_count_24h=velocity,
    )
    return txn, expected


async def _utterances(
    llm: LLMClient, rng: random.Random, archetype: ScamArchetype, adversarial: bool, legit_brief: str | None
) -> list[str]:
    if legit_brief is not None:
        brief = (
            f"This customer is legitimately {legit_brief}. Nobody instructed them to do it; "
            "they arranged it themselves and are mildly puzzled the bank is asking."
        )
        fallback = [rng.choice(_LEGIT_TEMPLATES)]
    else:
        brief = SCAM_BRIEFS[archetype]
        fallback = list(_TEMPLATE_FALLBACK[archetype])

    if not llm.enabled:
        return fallback

    system = _UTTERANCE_SYSTEM + (_ADVERSARIAL_NOTE if adversarial else "")
    out = await llm.complete_json(system, f"Situation: {brief}", temperature=1.0)
    lines = (out or {}).get("lines")
    if isinstance(lines, list) and lines:
        return [str(x).strip() for x in lines if str(x).strip()][:4]
    return fallback


async def build(n: int, seed: int, use_llm: bool) -> Dataset:
    rng = random.Random(seed)
    settings = get_settings()
    llm = LLMClient(settings)
    live = use_llm and llm.enabled

    # Weighted so the legitimate half — the half that produces false positives — is the
    # larger one. A scam detector is easy to make sensitive and hard to make quiet.
    plan: list[tuple[Slice, ScamArchetype | None]] = []
    archetypes = list(SCAM_BRIEFS)
    n_clean = int(n * 0.30)
    n_adv = int(n * 0.12)
    n_susp = int(n * 0.38)
    n_obvious = n - n_clean - n_adv - n_susp
    for i in range(n_clean):
        plan.append((Slice.scam_clean, archetypes[i % len(archetypes)]))
    for i in range(n_adv):
        plan.append((Slice.scam_adversarial, archetypes[i % len(archetypes)]))
    plan += [(Slice.legit_suspicious, None)] * n_susp
    plan += [(Slice.legit_obvious, None)] * n_obvious
    rng.shuffle(plan)

    sem = asyncio.Semaphore(8)

    async def one(idx: int, slice_: Slice, arch: ScamArchetype | None) -> EvalCase:
        is_scam = arch is not None
        prof = (
            SCAM_PROFILE if is_scam
            else LEGIT_SUSPICIOUS_PROFILE if slice_ is Slice.legit_suspicious
            else LEGIT_OBVIOUS_PROFILE
        )
        # Scams over-target the elderly; legitimate large transfers skew younger but not
        # exclusively, so age can't be used as a giveaway.
        elderly = rng.random() < (0.6 if is_scam else 0.3)
        cust = _profile(rng, idx, elderly)
        txn, expected = _transaction(rng, idx, cust, prof)
        legit_brief = None if is_scam else rng.choice(LEGIT_BRIEFS)

        async with sem:
            lines = await _utterances(
                llm, rng, arch or ScamArchetype.none,
                adversarial=slice_ is Slice.scam_adversarial,
                legit_brief=legit_brief,
            )

        return EvalCase(
            id=f"case_{idx:04d}",
            slice=slice_,
            is_scam=is_scam,
            archetype=arch or ScamArchetype.none,
            customer=cust,
            transaction=txn,
            utterances=lines,
            expected_signals=sorted(set(expected)),
            rationale=(SCAM_BRIEFS[arch][:90] + "…") if arch else f"Legitimate: {legit_brief}",
        )

    cases = await asyncio.gather(*(one(i, s, a) for i, (s, a) in enumerate(plan)))

    return Dataset(
        version="1.0",
        generated_at=utc(),
        generator="llm" if live else "template",
        notes=(
            "Synthetic. Transfer features are drawn from the seeded distributions in "
            "eval/generate.py; utterances are LLM-generated from plain-language scam briefs "
            "that never include the classifier's indicator lists. Tests internal consistency, "
            "not real-world validity — see eval/results/REPORT.md."
        ),
        cases=list(cases),
    )


async def _main() -> None:
    ap = argparse.ArgumentParser(description="Generate the HyperGuard evaluation dataset.")
    ap.add_argument("--n", type=int, default=320)
    ap.add_argument("--seed", type=int, default=7)
    ap.add_argument("--no-llm", action="store_true", help="offline template utterances")
    ap.add_argument("--out", type=Path, default=DATA_PATH)
    args = ap.parse_args()

    ds = await build(args.n, args.seed, use_llm=not args.no_llm)
    args.out.write_text(
        json.dumps(json.loads(ds.model_dump_json()), indent=1), encoding="utf-8"
    )
    print(f"wrote {len(ds.cases)} cases → {args.out}  (utterances: {ds.generator})")
    for k, v in sorted(ds.counts().items()):
        print(f"  {k:<20} {v}")


def load(path: Path = DATA_PATH) -> Dataset:
    if not path.exists():
        raise SystemExit(
            f"No dataset at {path}. Build one first:  python -m eval.generate --n 320"
        )
    return Dataset.model_validate_json(path.read_text(encoding="utf-8"))


if __name__ == "__main__":
    asyncio.run(_main())
